content:
{
  "patches": [
    {
      "path": "styles.css",
      "oldString": ".class-card p {
  font-size: 0.875rem;
  color: var(--color-text-muted);
}",
      "newString": ".class-card p {
  font-size: 1rem;
  line-height: 1.5;
  color: var(--color-text-muted);
  margin-bottom: 1rem;
}

.class-card[data-kind="도자기"] .class-art::before {
  content: "";
  display: block;
  width: 100%;
  padding-top: 66.67%; /* 3:2 aspect ratio */
  background: radial-gradient(circle at 50% 40%, #e8dcd4 0%, #dcbba9 100%);
  border-radius: 0 0 50% 50% / 0 0 100% 100%;
  position: relative;
}

.class-card[data-kind="도자기"] .class-art::after {
  content: "";
  position: absolute;
  top: 20%;
  left: 50%;
  transform: translateX(-50%);
  width: 60%;
  height: 40%;
  border: 4px solid rgba(139, 69, 19, 0.2);
  border-radius: 50%;
}

.class-card[data-kind="가죽공예"] .class-art::before {
  content: "";
  display: block;
  width: 100%;
  padding-top: 66.67%;
  background: #f5f0eb;
  position: relative;
  overflow: hidden;
}

.class-card[data-kind="가죽공예"] .class-art::after {
  content: "";
  position: absolute;
  top: 30%;
  left: 20%;
  width: 60%;
  height: 40%;
  background: #8b5a2b;
  border-radius: 4px;
  box-shadow: inset 0 0 0 2px #dcbba9;
}

.class-card[data-kind="목공예"] .class-art::before {
  content: "";
  display: block;
  width: 100%;
  padding-top: 66.67%;
  background: #e8dcd4;
  position: relative;
}

.class-card[data-kind="목공예"] .class-art::after {
  content: "";
  position: absolute;
  top: 25%;
  left: 10%;
  width: 80%;
  height: 50%;
  background: #a67c52;
  border-radius: 4px;
  box-shadow: inset 0 0 0 2px #dcbba9;
}

.class-art {
  width: 100%;
  height: auto;
  margin-bottom: 1rem;
}

.class-logistics {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 1rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-secondary);
}

.class-logistics svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  fill: var(--color-text-secondary);
}

.class-price {
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--color-text-primary);
  margin-top: auto;
  padding-top: 0.5rem;
}"
    }
  ]
}
